def slack_list_channels(installation_id, cursor=None, limit=None, include_archived=None, types=None, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0144000" if __import__("os").path.isdir("./environment_mix/0144000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, installation_row_id=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        rid = f"req_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{len(logs)+1}"
        row = {
            "id": rid,
            "endpoint": "slack_list_channels",
            "installation_id": installation_row_id,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now,
        }
        if meta is not None:
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    def _parse_cursor(c):
        if c is None:
            return 0
        if not isinstance(c, str):
            return None
        c = c.strip()
        if c == "":
            return None
        if c.isdigit():
            return int(c)
        try:
            raw = base64.urlsafe_b64decode(c.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            if isinstance(obj, dict) and "offset" in obj and isinstance(obj["offset"], int) and obj["offset"] >= 0:
                return obj["offset"]
        except Exception:
            return None
        return None

    def _make_cursor(offset):
        payload = json.dumps({"offset": offset}, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(payload).decode("utf-8").rstrip("=")

    try:
        if not isinstance(installation_id, str) or not re.match(r"^slk_inst_[0-9A-Z]{17,}$", installation_id):
            _log("VALIDATION_ERROR", None, {"field": "installation_id"})
            return _err("VALIDATION_ERROR", "installation_id is invalid.", field="installation_id")

        if cursor is not None and not isinstance(cursor, str):
            _log("VALIDATION_ERROR", installation_id, {"field": "cursor"})
            return _err("VALIDATION_ERROR", "cursor must be a string.", field="cursor")

        if limit is None:
            limit = 100
        if not isinstance(limit, int) or limit < 1 or limit > 1000:
            _log("VALIDATION_ERROR", installation_id, {"field": "limit"})
            return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 1000.", field="limit")

        if include_archived is None:
            include_archived = False
        if not isinstance(include_archived, bool):
            _log("VALIDATION_ERROR", installation_id, {"field": "include_archived"})
            return _err("VALIDATION_ERROR", "include_archived must be a boolean.", field="include_archived")

        allowed_types = {"public_channel", "private_channel"}
        if types is not None:
            if not isinstance(types, list) or any((not isinstance(x, str) or x not in allowed_types) for x in types):
                _log("VALIDATION_ERROR", installation_id, {"field": "types"})
                return _err("VALIDATION_ERROR", "types must be an array of 'public_channel' and/or 'private_channel'.", field="types")
            types = list(dict.fromkeys(types))  # de-dupe preserve order

        offset = _parse_cursor(cursor)
        if offset is None:
            _log("VALIDATION_ERROR", installation_id, {"field": "cursor"})
            return _err("VALIDATION_ERROR", "cursor is invalid.", field="cursor")

        installs = _load("slack_installations.json")
        inst = next((r for r in installs if isinstance(r, dict) and r.get("id") == installation_id), None)
        if not inst:
            _log("NOT_FOUND", installation_id)
            return _err("NOT_FOUND", "Installation not found.", installation_id=installation_id)

        # Business rule: all tools operate within exactly one active installation; if none exists => configuration error
        active_exists = any(isinstance(r, dict) and r.get("status") == "active" for r in installs)
        if not active_exists:
            _log("UNAUTHORIZED", installation_id, {"reason": "no_active_installation"})
            return _err("UNAUTHORIZED", "No active Slack installation is configured.")

        if inst.get("status") != "active":
            _log("UNAUTHORIZED", installation_id, {"reason": "installation_not_active"})
            return _err("UNAUTHORIZED", "Installation is not active.", status=inst.get("status"))

        chs = _load("slack_channels.json")
        rows = []
        for ch in chs if isinstance(chs, list) else []:
            if not isinstance(ch, dict):
                continue
            if ch.get("installation_id") != installation_id:
                continue
            st = ch.get("status")
            if st not in ("active", "archived"):
                continue
            if not include_archived and (ch.get("is_archived") is True or st == "archived"):
                continue
            if types:
                # Map channel privacy to type
                is_priv = bool(ch.get("is_private"))
                ch_type = "private_channel" if is_priv else "public_channel"
                if ch_type not in types:
                    continue
            rows.append(ch)

        # Ordering: name asc with nulls last.
        def _name_key(r):
            nm = r.get("name")
            if nm is None:
                return (1, "")
            if not isinstance(nm, str):
                nm = str(nm)
            return (0, nm.lower())

        rows.sort(key=_name_key)

        total = len(rows)
        page = rows[offset: offset + limit]
        next_offset = offset + len(page)
        has_more = next_offset < total
        next_cursor = _make_cursor(next_offset) if has_more else None

        _log("OK", installation_id, {"returned": len(page), "total": total, "has_more": has_more})
        return {
            "channels": page,
            "pagination": {
                "total": total,
                "limit": limit,
                "cursor": cursor,
                "next_cursor": next_cursor,
                "has_more": has_more
            }
        }
    except Exception as e:
        _log("ERROR", installation_id if isinstance(installation_id, str) else None, {"exception": type(e).__name__})
        return _err("CONFLICT", "Internal error.")

def slack_post_message(installation_id, channel_id, text, blocks=None, attachments=None, **_extra):
    import json, os, datetime, re, time, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0144000" if __import__("os").path.isdir("./environment_mix/0144000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _log(status, installation_row_id=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        rid = f"req_{now_dt.strftime('%Y%m%d%H%M%S')}_{len(logs)+1}"
        row = {
            "id": rid,
            "endpoint": "slack_post_message",
            "installation_id": installation_row_id,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now,
        }
        if meta is not None:
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    def _new_id(prefix, existing_ids):
        # 18 chars base36-ish uppercase
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        for _ in range(50):
            s = "".join(random.choice(alphabet) for _ in range(18))
            nid = f"{prefix}_{s}"
            if nid not in existing_ids:
                return nid
        return f"{prefix}_{now_dt.strftime('%Y%m%d%H%M%S')}{random.randint(1000,9999)}"

    def _slack_ts():
        secs = int(time.time())
        micros = int((time.time() - secs) * 1_000_000)
        return f"{secs}.{micros:06d}"

    def _required_scopes_ok(scopes, req):
        if not isinstance(scopes, list):
            return False
        sset = set([x for x in scopes if isinstance(x, str)])
        return all(r in sset for r in req)

    try:
        if not isinstance(installation_id, str) or not re.match(r"^slk_inst_[0-9A-Z]{17,}$", installation_id):
            _log("VALIDATION_ERROR", None, {"field": "installation_id"})
            return _err("VALIDATION_ERROR", "installation_id is invalid.", field="installation_id")
        if not isinstance(channel_id, str) or not re.match(r"^slk_chn_[0-9A-Z]{17,}$", channel_id):
            _log("VALIDATION_ERROR", installation_id, {"field": "channel_id"})
            return _err("VALIDATION_ERROR", "channel_id is invalid.", field="channel_id")
        if not isinstance(text, str) or text.strip() == "":
            _log("VALIDATION_ERROR", installation_id, {"field": "text"})
            return _err("VALIDATION_ERROR", "text must be a non-empty string.", field="text")
        if blocks is not None and not isinstance(blocks, (dict, list)):
            _log("VALIDATION_ERROR", installation_id, {"field": "blocks"})
            return _err("VALIDATION_ERROR", "blocks must be an object/array payload.", field="blocks")
        if attachments is not None and not isinstance(attachments, (dict, list)):
            _log("VALIDATION_ERROR", installation_id, {"field": "attachments"})
            return _err("VALIDATION_ERROR", "attachments must be an object/array payload.", field="attachments")

        installs = _load("slack_installations.json")
        inst = next((r for r in installs if isinstance(r, dict) and r.get("id") == installation_id), None)
        if not inst:
            _log("NOT_FOUND", installation_id)
            return _err("NOT_FOUND", "Installation not found.", installation_id=installation_id)

        active_exists = any(isinstance(r, dict) and r.get("status") == "active" for r in installs)
        if not active_exists:
            _log("UNAUTHORIZED", installation_id, {"reason": "no_active_installation"})
            return _err("UNAUTHORIZED", "No active Slack installation is configured.")
        if inst.get("status") != "active":
            _log("UNAUTHORIZED", installation_id, {"reason": "installation_not_active"})
            return _err("UNAUTHORIZED", "Installation is not active.", status=inst.get("status"))

        # Scope enforcement
        if not _required_scopes_ok(inst.get("scopes"), ["chat:write"]):
            _log("UNAUTHORIZED", installation_id, {"reason": "missing_scope", "required": ["chat:write"]})
            return _err("UNAUTHORIZED", "Installation is missing required scopes.", required_scopes=["chat:write"])

        channels = _load("slack_channels.json")
        ch = next((r for r in channels if isinstance(r, dict) and r.get("id") == channel_id), None)
        if not ch or ch.get("installation_id") != installation_id:
            _log("NOT_FOUND", installation_id, {"channel_id": channel_id})
            return _err("NOT_FOUND", "Channel not found for installation.", channel_id=channel_id)

        if bool(ch.get("is_archived")) is True:
            _log("CONFLICT", installation_id, {"reason": "channel_archived", "channel_id": channel_id})
            return _err("CONFLICT", "Cannot post to an archived channel.", channel_id=channel_id)

        slack_channel_id = ch.get("slack_channel_id")
        if not isinstance(slack_channel_id, str) or slack_channel_id.strip() == "":
            _log("CONFLICT", installation_id, {"reason": "missing_slack_channel_id", "channel_id": channel_id})
            return _err("CONFLICT", "Channel cache row is missing slack_channel_id.", channel_id=channel_id)

        # Offline "Slack API call" simulation: generate a slack_ts and store.
        slack_ts = _slack_ts()
        slack_created_at = now_dt.isoformat() + "Z"

        msgs = _load("slack_messages.json")
        if not isinstance(msgs, list):
            msgs = []

        # Upsert unique(installation_id, slack_channel_id, slack_ts)
        existing = next((m for m in msgs if isinstance(m, dict) and m.get("installation_id") == installation_id and m.get("slack_channel_id") == slack_channel_id and m.get("slack_ts") == slack_ts), None)

        msg_ids = set([m.get("id") for m in msgs if isinstance(m, dict) and isinstance(m.get("id"), str)])
        if existing:
            # Idempotent for same slack_ts: update content
            existing["channel_id"] = channel_id
            existing["text"] = text
            existing["blocks"] = blocks
            existing["attachments"] = attachments
            existing["message_type"] = "message"
            existing["posted_via"] = "api"
            existing["status"] = existing.get("status") if existing.get("status") in ("visible", "deleted") else "visible"
            existing["slack_created_at"] = existing.get("slack_created_at") or slack_created_at
            existing["updated_at"] = now
            out = existing
        else:
            mid = _new_id("slk_msg", msg_ids)
            out = {
                "id": mid,
                "installation_id": installation_id,
                "channel_id": channel_id,
                "slack_channel_id": slack_channel_id,
                "slack_ts": slack_ts,
                "thread_ts": slack_ts,  # root
                "parent_message_id": None,
                "author_user_id": None,
                "slack_author_user_id": inst.get("bot_user_id"),
                "text": text,
                "blocks": blocks,
                "attachments": attachments,
                "message_type": "message",
                "posted_via": "api",
                "status": "visible",
                "slack_permalink": None,
                "slack_created_at": slack_created_at,
                "created_at": now,
                "updated_at": now
            }
            msgs.append(out)

        _save("slack_messages.json", msgs)
        _log("OK", installation_id, {"message_id": out.get("id"), "slack_ts": slack_ts, "channel_id": channel_id})
        return {"message": out}
    except Exception as e:
        _log("ERROR", installation_id if isinstance(installation_id, str) else None, {"exception": type(e).__name__})
        return _err("CONFLICT", "Internal error.")

def slack_reply_to_thread(installation_id, parent_message_id, text, blocks=None, attachments=None, **_extra):
    import json, os, datetime, re, time, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0144000" if __import__("os").path.isdir("./environment_mix/0144000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _log(status, installation_row_id=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        rid = f"req_{now_dt.strftime('%Y%m%d%H%M%S')}_{len(logs)+1}"
        row = {
            "id": rid,
            "endpoint": "slack_reply_to_thread",
            "installation_id": installation_row_id,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now,
        }
        if meta is not None:
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    def _new_id(prefix, existing_ids):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        for _ in range(50):
            s = "".join(random.choice(alphabet) for _ in range(18))
            nid = f"{prefix}_{s}"
            if nid not in existing_ids:
                return nid
        return f"{prefix}_{now_dt.strftime('%Y%m%d%H%M%S')}{random.randint(1000,9999)}"

    def _slack_ts():
        secs = int(time.time())
        micros = int((time.time() - secs) * 1_000_000)
        return f"{secs}.{micros:06d}"

    def _required_scopes_ok(scopes, req):
        if not isinstance(scopes, list):
            return False
        sset = set([x for x in scopes if isinstance(x, str)])
        return all(r in sset for r in req)

    try:
        if not isinstance(installation_id, str) or not re.match(r"^slk_inst_[0-9A-Z]{17,}$", installation_id):
            _log("VALIDATION_ERROR", None, {"field": "installation_id"})
            return _err("VALIDATION_ERROR", "installation_id is invalid.", field="installation_id")
        if not isinstance(parent_message_id, str) or not re.match(r"^slk_msg_[0-9A-Z]{17,}$", parent_message_id):
            _log("VALIDATION_ERROR", installation_id, {"field": "parent_message_id"})
            return _err("VALIDATION_ERROR", "parent_message_id is invalid.", field="parent_message_id")
        if not isinstance(text, str) or text.strip() == "":
            _log("VALIDATION_ERROR", installation_id, {"field": "text"})
            return _err("VALIDATION_ERROR", "text must be a non-empty string.", field="text")
        if blocks is not None and not isinstance(blocks, (dict, list)):
            _log("VALIDATION_ERROR", installation_id, {"field": "blocks"})
            return _err("VALIDATION_ERROR", "blocks must be an object/array payload.", field="blocks")
        if attachments is not None and not isinstance(attachments, (dict, list)):
            _log("VALIDATION_ERROR", installation_id, {"field": "attachments"})
            return _err("VALIDATION_ERROR", "attachments must be an object/array payload.", field="attachments")

        installs = _load("slack_installations.json")
        inst = next((r for r in installs if isinstance(r, dict) and r.get("id") == installation_id), None)
        if not inst:
            _log("NOT_FOUND", installation_id)
            return _err("NOT_FOUND", "Installation not found.", installation_id=installation_id)

        active_exists = any(isinstance(r, dict) and r.get("status") == "active" for r in installs)
        if not active_exists:
            _log("UNAUTHORIZED", installation_id, {"reason": "no_active_installation"})
            return _err("UNAUTHORIZED", "No active Slack installation is configured.")
        if inst.get("status") != "active":
            _log("UNAUTHORIZED", installation_id, {"reason": "installation_not_active"})
            return _err("UNAUTHORIZED", "Installation is not active.", status=inst.get("status"))

        if not _required_scopes_ok(inst.get("scopes"), ["chat:write"]):
            _log("UNAUTHORIZED", installation_id, {"reason": "missing_scope", "required": ["chat:write"]})
            return _err("UNAUTHORIZED", "Installation is missing required scopes.", required_scopes=["chat:write"])

        msgs = _load("slack_messages.json")
        if not isinstance(msgs, list):
            msgs = []

        parent = next((m for m in msgs if isinstance(m, dict) and m.get("id") == parent_message_id), None)
        if not parent or parent.get("installation_id") != installation_id:
            _log("NOT_FOUND", installation_id, {"parent_message_id": parent_message_id})
            return _err("NOT_FOUND", "Parent message not found for installation.", parent_message_id=parent_message_id)

        if parent.get("status") == "deleted":
            _log("CONFLICT", installation_id, {"reason": "parent_deleted", "parent_message_id": parent_message_id})
            return _err("CONFLICT", "Cannot reply to a deleted parent message.", parent_message_id=parent_message_id)

        # Determine thread root ts. If parent has thread_ts use it; else if it's a root message, use its slack_ts.
        thread_ts = parent.get("thread_ts") or parent.get("slack_ts")
        if not isinstance(thread_ts, str) or thread_ts.strip() == "":
            _log("CONFLICT", installation_id, {"reason": "parent_not_threadable"})
            return _err("CONFLICT", "Parent message is not threadable (missing thread_ts/slack_ts).", parent_message_id=parent_message_id)

        channel_id = parent.get("channel_id")
        slack_channel_id = parent.get("slack_channel_id")
        if not isinstance(channel_id, str) or not isinstance(slack_channel_id, str):
            _log("CONFLICT", installation_id, {"reason": "parent_missing_channel_linkage"})
            return _err("CONFLICT", "Parent message is missing channel linkage.", parent_message_id=parent_message_id)

        # Must only allow posting to existing cached channel and not archived
        channels = _load("slack_channels.json")
        ch = next((c for c in channels if isinstance(c, dict) and c.get("id") == channel_id), None)
        if not ch or ch.get("installation_id") != installation_id:
            _log("NOT_FOUND", installation_id, {"channel_id": channel_id})
            return _err("NOT_FOUND", "Channel not found for installation.", channel_id=channel_id)
        if bool(ch.get("is_archived")) is True:
            _log("CONFLICT", installation_id, {"reason": "channel_archived", "channel_id": channel_id})
            return _err("CONFLICT", "Cannot reply in an archived channel.", channel_id=channel_id)

        # Offline Slack call simulation
        slack_ts = _slack_ts()
        slack_created_at = now_dt.isoformat() + "Z"

        # Parent/root message exists: set parent_message_id accordingly (root preferred)
        root = None
        if parent.get("thread_ts") and parent.get("thread_ts") != parent.get("slack_ts"):
            # parent is a reply; try find root by thread_ts
            root = next((m for m in msgs if isinstance(m, dict) and m.get("installation_id") == installation_id and m.get("slack_channel_id") == slack_channel_id and m.get("slack_ts") == thread_ts), None)
        else:
            root = parent
        parent_link_id = root.get("id") if isinstance(root, dict) else parent_message_id

        msg_ids = set([m.get("id") for m in msgs if isinstance(m, dict) and isinstance(m.get("id"), str)])
        existing = next((m for m in msgs if isinstance(m, dict) and m.get("installation_id") == installation_id and m.get("slack_channel_id") == slack_channel_id and m.get("slack_ts") == slack_ts), None)

        if existing:
            existing["channel_id"] = channel_id
            existing["thread_ts"] = thread_ts
            existing["parent_message_id"] = parent_link_id
            existing["text"] = text
            existing["blocks"] = blocks
            existing["attachments"] = attachments
            existing["message_type"] = "reply"
            existing["posted_via"] = "api"
            existing["status"] = existing.get("status") if existing.get("status") in ("visible", "deleted") else "visible"
            existing["slack_created_at"] = existing.get("slack_created_at") or slack_created_at
            existing["updated_at"] = now
            out = existing
        else:
            mid = _new_id("slk_msg", msg_ids)
            out = {
                "id": mid,
                "installation_id": installation_id,
                "channel_id": channel_id,
                "slack_channel_id": slack_channel_id,
                "slack_ts": slack_ts,
                "thread_ts": thread_ts,
                "parent_message_id": parent_link_id,
                "author_user_id": None,
                "slack_author_user_id": inst.get("bot_user_id"),
                "text": text,
                "blocks": blocks,
                "attachments": attachments,
                "message_type": "reply",
                "posted_via": "api",
                "status": "visible",
                "slack_permalink": None,
                "slack_created_at": slack_created_at,
                "created_at": now,
                "updated_at": now
            }
            msgs.append(out)

        _save("slack_messages.json", msgs)
        _log("OK", installation_id, {"reply_message_id": out.get("id"), "thread_ts": thread_ts, "parent_message_id": parent_message_id})
        return {"message": out}
    except Exception as e:
        _log("ERROR", installation_id if isinstance(installation_id, str) else None, {"exception": type(e).__name__})
        return _err("CONFLICT", "Internal error.")

def slack_add_reaction(installation_id, message_id, emoji_name, **_extra):
    import json, os, datetime, re, time, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0144000" if __import__("os").path.isdir("./environment_mix/0144000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _log(status, installation_row_id=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        rid = f"req_{now_dt.strftime('%Y%m%d%H%M%S')}_{len(logs)+1}"
        row = {
            "id": rid,
            "endpoint": "slack_add_reaction",
            "installation_id": installation_row_id,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now,
        }
        if meta is not None:
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    def _new_id(prefix, existing_ids):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        for _ in range(50):
            s = "".join(random.choice(alphabet) for _ in range(18))
            nid = f"{prefix}_{s}"
            if nid not in existing_ids:
                return nid
        return f"{prefix}_{now_dt.strftime('%Y%m%d%H%M%S')}{random.randint(1000,9999)}"

    def _required_scopes_ok(scopes, req):
        if not isinstance(scopes, list):
            return False
        sset = set([x for x in scopes if isinstance(x, str)])
        return all(r in sset for r in req)

    try:
        if not isinstance(installation_id, str) or not re.match(r"^slk_inst_[0-9A-Z]{17,}$", installation_id):
            _log("VALIDATION_ERROR", None, {"field": "installation_id"})
            return _err("VALIDATION_ERROR", "installation_id is invalid.", field="installation_id")
        if not isinstance(message_id, str) or not re.match(r"^slk_msg_[0-9A-Z]{17,}$", message_id):
            _log("VALIDATION_ERROR", installation_id, {"field": "message_id"})
            return _err("VALIDATION_ERROR", "message_id is invalid.", field="message_id")
        if not isinstance(emoji_name, str) or emoji_name.strip() == "":
            _log("VALIDATION_ERROR", installation_id, {"field": "emoji_name"})
            return _err("VALIDATION_ERROR", "emoji_name must be a non-empty string.", field="emoji_name")
        # Basic slack emoji name validation: letters/numbers/_/+/-
        if not re.match(r"^[a-z0-9_+\-]{1,64}$", emoji_name.strip().lower()):
            _log("VALIDATION_ERROR", installation_id, {"field": "emoji_name"})
            return _err("VALIDATION_ERROR", "emoji_name is invalid.", field="emoji_name")

        installs = _load("slack_installations.json")
        inst = next((r for r in installs if isinstance(r, dict) and r.get("id") == installation_id), None)
        if not inst:
            _log("NOT_FOUND", installation_id)
            return _err("NOT_FOUND", "Installation not found.", installation_id=installation_id)

        active_exists = any(isinstance(r, dict) and r.get("status") == "active" for r in installs)
        if not active_exists:
            _log("UNAUTHORIZED", installation_id, {"reason": "no_active_installation"})
            return _err("UNAUTHORIZED", "No active Slack installation is configured.")
        if inst.get("status") != "active":
            _log("UNAUTHORIZED", installation_id, {"reason": "installation_not_active"})
            return _err("UNAUTHORIZED", "Installation is not active.", status=inst.get("status"))

        if not _required_scopes_ok(inst.get("scopes"), ["reactions:write"]):
            _log("UNAUTHORIZED", installation_id, {"reason": "missing_scope", "required": ["reactions:write"]})
            return _err("UNAUTHORIZED", "Installation is missing required scopes.", required_scopes=["reactions:write"])

        msgs = _load("slack_messages.json")
        if not isinstance(msgs, list):
            msgs = []
        msg = next((m for m in msgs if isinstance(m, dict) and m.get("id") == message_id), None)
        if not msg or msg.get("installation_id") != installation_id:
            _log("NOT_FOUND", installation_id, {"message_id": message_id})
            return _err("NOT_FOUND", "Message not found for installation.", message_id=message_id)

        if msg.get("status") == "deleted":
            _log("CONFLICT", installation_id, {"reason": "message_deleted", "message_id": message_id})
            return _err("CONFLICT", "Cannot react to a deleted message.", message_id=message_id)

        slack_channel_id = msg.get("slack_channel_id")
        slack_ts = msg.get("slack_ts")
        if not isinstance(slack_channel_id, str) or slack_channel_id.strip() == "" or not isinstance(slack_ts, str) or slack_ts.strip() == "":
            _log("CONFLICT", installation_id, {"reason": "missing_slack_identifiers", "message_id": message_id})
            return _err("CONFLICT", "Message is missing slack_channel_id/slack_ts required for reactions.", message_id=message_id)

        reactions = _load("slack_reactions.json")
        if not isinstance(reactions, list):
            reactions = []

        slack_reacting_user_id = inst.get("bot_user_id")
        # Enforce unique(installation_id, message_id, emoji_name, slack_reacting_user_id)
        emoji_norm = emoji_name.strip().lower()
        existing = next(
            (r for r in reactions
             if isinstance(r, dict)
             and r.get("installation_id") == installation_id
             and r.get("message_id") == message_id
             and (r.get("emoji_name") or "").lower() == emoji_norm
             and (r.get("slack_reacting_user_id") == slack_reacting_user_id)),
            None
        )

        reaction_ids = set([r.get("id") for r in reactions if isinstance(r, dict) and isinstance(r.get("id"), str)])
        if existing:
            # Idempotent: ensure active
            if existing.get("status") == "removed":
                existing["status"] = "active"
            existing["posted_via"] = "api"
            existing["updated_at"] = now
            out_reaction = existing
        else:
            rid = _new_id("slk_react", reaction_ids)
            out_reaction = {
                "id": rid,
                "installation_id": installation_id,
                "message_id": message_id,
                "slack_channel_id": slack_channel_id,
                "slack_message_ts": slack_ts,
                "emoji_name": emoji_norm,
                "reacting_user_id": None,
                "slack_reacting_user_id": slack_reacting_user_id,
                "posted_via": "api",
                "status": "active",
                "created_at": now,
                "updated_at": now
            }
            reactions.append(out_reaction)

        _save("slack_reactions.json", reactions)
        _log("OK", installation_id, {"message_id": message_id, "reaction_id": out_reaction.get("id"), "emoji_name": emoji_norm})
        return {"message": msg, "reaction": out_reaction}
    except Exception as e:
        _log("ERROR", installation_id if isinstance(installation_id, str) else None, {"exception": type(e).__name__})
        return _err("CONFLICT", "Internal error.")

def slack_get_channel_history(installation_id, channel_id, cursor=None, limit=None, oldest=None, latest=None, inclusive=None, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0144000" if __import__("os").path.isdir("./environment_mix/0144000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "slack_get_channel_history"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_ts(ts):
        # Slack ts is a string like "1712345678.123456"
        if ts is None:
            return None
        if not isinstance(ts, str) or ts.strip() == "":
            return None
        try:
            if "." in ts:
                a, b = ts.split(".", 1)
                if a == "" or b == "":
                    return None
                return (int(a), int((b + "000000")[:6]))
            return (int(ts), 0)
        except Exception:
            return None

    def _cmp_ts(a, b):
        return (a > b) - (a < b)

    def _decode_cursor(cur):
        if cur is None:
            return 0
        if not isinstance(cur, str):
            return None
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict) or obj.get("v") != 1:
                return None
            off = obj.get("offset")
            if not isinstance(off, int) or off < 0:
                return None
            return off
        except Exception:
            return None

    def _encode_cursor(off):
        payload = json.dumps({"v": 1, "offset": off}, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(payload).decode("utf-8").rstrip("=")

    # Basic validation
    if not isinstance(installation_id, str) or not re.match(r"^slk_inst_[0-9A-Z]{17,}$", installation_id):
        return _err("VALIDATION_ERROR", "installation_id is invalid.")
    if not isinstance(channel_id, str) or not re.match(r"^slk_chn_[0-9A-Z]{17,}$", channel_id):
        return _err("VALIDATION_ERROR", "channel_id is invalid.")
    if limit is None:
        limit = 100
    if not isinstance(limit, int) or limit < 1 or limit > 1000:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 1000.")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string.")
    if inclusive is None:
        inclusive = False
    if not isinstance(inclusive, bool):
        return _err("VALIDATION_ERROR", "inclusive must be a boolean.")
    o_ts = _parse_ts(oldest) if oldest is not None else None
    l_ts = _parse_ts(latest) if latest is not None else None
    if oldest is not None and o_ts is None:
        return _err("VALIDATION_ERROR", "oldest must be a valid Slack ts string.")
    if latest is not None and l_ts is None:
        return _err("VALIDATION_ERROR", "latest must be a valid Slack ts string.")
    if o_ts is not None and l_ts is not None and _cmp_ts(o_ts, l_ts) > 0:
        return _err("VALIDATION_ERROR", "oldest must be <= latest.")

    installations = _load("slack_installations.json")
    channels = _load("slack_channels.json")
    messages = _load("slack_messages.json")

    # Enforce business rule: tools operate within exactly one active installation; if none exists -> configuration error.
    active_insts = [r for r in installations if isinstance(r, dict) and r.get("status") == "active"]
    if len(active_insts) == 0:
        return _err("UNAUTHORIZED", "No active Slack installation is configured.")
    inst = next((r for r in active_insts if r.get("id") == installation_id), None)
    if not inst:
        return _err("NOT_FOUND", "Installation not found or not active.")

    # Token scope enforcement: history read requires channels:history (and groups:history for private channels).
    # We'll determine channel privacy below. Reject if missing required scope.
    ch = next((c for c in channels if isinstance(c, dict) and c.get("id") == channel_id and c.get("installation_id") == installation_id), None)
    if not ch:
        return _err("NOT_FOUND", "Channel not found for this installation.")
    if ch.get("status") not in ("active", "archived"):
        return _err("NOT_FOUND", "Channel not found for this installation.")
    scopes = inst.get("scopes") if isinstance(inst.get("scopes"), list) else []
    required = "groups:history" if bool(ch.get("is_private")) else "channels:history"
    if required not in scopes:
        return _err("UNAUTHORIZED", f"Missing required scope: {required}.")

    # Pagination cursor
    offset = _decode_cursor(cursor)
    if offset is None:
        return _err("VALIDATION_ERROR", "cursor is invalid.")

    # Filter messages
    ch_slack_id = ch.get("slack_channel_id")
    rows = []
    for m in messages:
        if not isinstance(m, dict):
            continue
        if m.get("installation_id") != installation_id:
            continue
        if m.get("channel_id") != channel_id:
            continue
        # Exclude deleted by default
        if m.get("status") == "deleted":
            continue
        mts = _parse_ts(m.get("slack_ts"))
        if mts is None:
            continue
        if o_ts is not None:
            c = _cmp_ts(mts, o_ts)
            if c < 0 or (c == 0 and not inclusive):
                continue
        if l_ts is not None:
            c = _cmp_ts(mts, l_ts)
            if c > 0 or (c == 0 and not inclusive):
                continue
        # enforce denorm channel id consistency (best-effort)
        if ch_slack_id is not None and m.get("slack_channel_id") not in (None, ch_slack_id):
            continue
        rows.append(m)

    # Slack history order: newest -> oldest
    def _sort_key(m):
        mts = _parse_ts(m.get("slack_ts")) or (0, 0)
        return (-mts[0], -mts[1], m.get("id") or "")

    rows.sort(key=_sort_key)

    total = len(rows)
    page = rows[offset: offset + limit]
    next_off = offset + len(page)
    has_more = next_off < total
    next_cursor = _encode_cursor(next_off) if has_more else None

    return {
        "messages": page,
        "channel": {"id": ch.get("id"), "slack_channel_id": ch.get("slack_channel_id"), "name": ch.get("name")},
        "pagination": {"limit": limit, "cursor": cursor, "next_cursor": next_cursor, "has_more": has_more, "total": total},
        "meta": {"installation_id": installation_id, "endpoint": endpoint, "timestamp": _now_iso(), "latency_ms": int((time.time() - t0) * 1000)}
    }

def slack_get_thread_replies(installation_id, parent_message_id, cursor=None, limit=None, oldest=None, latest=None, inclusive=None, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0144000" if __import__("os").path.isdir("./environment_mix/0144000") else "/app/database")
    def _load(n):
