            return None
        if not isinstance(ts, str) or ts.strip() == "":
            return None
        try:
            if "." in ts:
                a, b = ts.split(".", 1)
                if a == "" or b == "":
                    return None
                return (int(a), int((b + "000000")[:6]))
            return (int(ts), 0)
        except Exception:
            return None

    def _cmp_ts(a, b):
        return (a > b) - (a < b)

    def _decode_cursor(cur):
        if cur is None:
            return 0
        if not isinstance(cur, str):
            return None
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict) or obj.get("v") != 1:
                return None
            off = obj.get("offset")
            if not isinstance(off, int) or off < 0:
                return None
            return off
        except Exception:
            return None

    def _encode_cursor(off):
        payload = json.dumps({"v": 1, "offset": off}, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(payload).decode("utf-8").rstrip("=")

    # Validation
    if not isinstance(installation_id, str) or not re.match(r"^slk_inst_[0-9A-Z]{17,}$", installation_id):
        return _err("VALIDATION_ERROR", "installation_id is invalid.")
    if not isinstance(parent_message_id, str) or not re.match(r"^slk_msg_[0-9A-Z]{17,}$", parent_message_id):
        return _err("VALIDATION_ERROR", "parent_message_id is invalid.")
    if limit is None:
        limit = 100
    if not isinstance(limit, int) or limit < 1 or limit > 1000:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 1000.")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string.")
    if inclusive is None:
        inclusive = False
    if not isinstance(inclusive, bool):
        return _err("VALIDATION_ERROR", "inclusive must be a boolean.")
    o_ts = _parse_ts(oldest) if oldest is not None else None
    l_ts = _parse_ts(latest) if latest is not None else None
    if oldest is not None and o_ts is None:
        return _err("VALIDATION_ERROR", "oldest must be a valid Slack ts string.")
    if latest is not None and l_ts is None:
        return _err("VALIDATION_ERROR", "latest must be a valid Slack ts string.")
    if o_ts is not None and l_ts is not None and _cmp_ts(o_ts, l_ts) > 0:
        return _err("VALIDATION_ERROR", "oldest must be <= latest.")

    installations = _load("slack_installations.json")
    channels = _load("slack_channels.json")
    messages = _load("slack_messages.json")

    active_insts = [r for r in installations if isinstance(r, dict) and r.get("status") == "active"]
    if len(active_insts) == 0:
        return _err("UNAUTHORIZED", "No active Slack installation is configured.")
    inst = next((r for r in active_insts if r.get("id") == installation_id), None)
    if not inst:
        return _err("NOT_FOUND", "Installation not found or not active.")

    parent = next((m for m in messages if isinstance(m, dict) and m.get("id") == parent_message_id and m.get("installation_id") == installation_id), None)
    if not parent:
        return _err("NOT_FOUND", "Parent message not found for this installation.")

    # Determine channel + scope requirements similar to history
    parent_channel_id = parent.get("channel_id")
    ch = next((c for c in channels if isinstance(c, dict) and c.get("id") == parent_channel_id and c.get("installation_id") == installation_id), None)
    if not ch:
        return _err("CONFLICT", "Parent message references a channel that is missing or outside this installation.")
    scopes = inst.get("scopes") if isinstance(inst.get("scopes"), list) else []
    required = "groups:history" if bool(ch.get("is_private")) else "channels:history"
    if required not in scopes:
        return _err("UNAUTHORIZED", f"Missing required scope: {required}.")

    thread_root_ts = parent.get("thread_ts") or parent.get("slack_ts")
    root_ts_parsed = _parse_ts(thread_root_ts)
    if root_ts_parsed is None:
        return _err("CONFLICT", "Parent message does not have a valid thread root timestamp.")

    offset = _decode_cursor(cursor)
    if offset is None:
        return _err("VALIDATION_ERROR", "cursor is invalid.")

    # Filter replies: channel matches, thread_ts equals root ts; visible only
    rows = []
    for m in messages:
        if not isinstance(m, dict):
            continue
        if m.get("installation_id") != installation_id:
            continue
        if m.get("channel_id") != parent_channel_id:
            continue
        if m.get("status") != "visible":
            continue
        if m.get("message_type") not in ("reply", "message"):
            continue
        if (m.get("thread_ts") or m.get("slack_ts")) != thread_root_ts and m.get("thread_ts") != thread_root_ts:
            continue

        mts = _parse_ts(m.get("slack_ts"))
        if mts is None:
            continue
        if o_ts is not None:
            c = _cmp_ts(mts, o_ts)
            if c < 0 or (c == 0 and not inclusive):
                continue
        if l_ts is not None:
            c = _cmp_ts(mts, l_ts)
            if c > 0 or (c == 0 and not inclusive):
                continue
        rows.append(m)

    # Thread replies are typically oldest->newest in Slack conversations.replies
    def _sort_key(m):
        mts = _parse_ts(m.get("slack_ts")) or (0, 0)
        return (mts[0], mts[1], m.get("id") or "")

    rows.sort(key=_sort_key)

    total = len(rows)
    page = rows[offset: offset + limit]
    next_off = offset + len(page)
    has_more = next_off < total
    next_cursor = _encode_cursor(next_off) if has_more else None

    return {
        "parent_message": parent,
        "replies": page,
        "pagination": {"limit": limit, "cursor": cursor, "next_cursor": next_cursor, "has_more": has_more, "total": total},
        "meta": {"installation_id": installation_id, "endpoint": endpoint, "timestamp": _now_iso(), "latency_ms": int((time.time() - t0) * 1000)}
    }

