        if not isinstance(u, dict):
            continue
        if u.get("installation_id") != installation_id:
            continue
        is_del = bool(u.get("is_deleted"))
        if is_del and u.get("status") != "deactivated":
            # inconsistent row: treat as deactivated for visibility; do not mutate on read
            u2 = dict(u)
            u2["status"] = "deactivated"
            u = u2
        if not include_deleted and is_del:
            continue
        filtered.append(u)

    # Sort stable: display_name, real_name, slack_user_id; nulls last
    def _nl(s):
        return (s is None, (s or "").lower())

    filtered.sort(key=lambda u: (_nl(u.get("display_name")), _nl(u.get("real_name")), (u.get("slack_user_id") or ""), (u.get("id") or "")))

    offset = _decode_cursor(cursor)
    if offset is None:
        return _err("VALIDATION_ERROR", "cursor is invalid.")

    total = len(filtered)
    page = filtered[offset: offset + limit]
    next_off = offset + len(page)
    has_more = next_off < total
    next_cursor = _encode_cursor(next_off) if has_more else None

    return {
        "users": page,
        "pagination": {"limit": limit, "cursor": cursor, "next_cursor": next_cursor, "has_more": has_more, "total": total},
        "meta": {"installation_id": installation_id, "endpoint": endpoint, "timestamp": _now_iso(), "latency_ms": int((time.time() - t0) * 1000)}
    }

def slack_get_user_profile(installation_id, user_id, **_extra):
    import json, os, datetime, time, secrets, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0144000" if __import__("os").path.isdir("./environment_mix/0144000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _unwrap_rows(obj):
        if isinstance(obj, dict) and isinstance(obj.get("rows"), list):
            return obj["rows"], True, obj
        if isinstance(obj, list):
            return obj, False, obj
        return [], False, obj

    def _save_rows(filename, rows, wrapped, original):
        if wrapped and isinstance(original, dict):
            original["rows"] = rows
            _save(filename, original)
        else:
            _save(filename, rows)

    def _append_log(status, installation=None, code=None, message=None):
        log_obj = _load("request_logs.json")
        rows, wrapped, original = _unwrap_rows(log_obj)
        if original == [] and not os.path.exists(os.path.join(_DB, "request_logs.json")):
            return
        if not isinstance(rows, list):
            return
        latency_ms = int((time.time() - t0) * 1000)
        entry = {
            "id": "req_" + secrets.token_hex(12),
            "endpoint": "slack_get_user_profile",
            "installation_id": installation,
            "status": status,
            "latency_ms": latency_ms,
            "timestamp": now,
        }
        if code is not None:
            entry["error_code"] = code
        if message is not None:
            entry["error_message"] = message
        rows.append(entry)
        _save_rows("request_logs.json", rows, wrapped, original)

    # ---- Validation (must follow tool schema patterns) ----
    inst_pat = re.compile(r"^slk_inst_[0-9A-Z]{17,}$")
    usr_pat = re.compile(r"^slk_usr_[0-9A-Z]{17,}$")
    if not isinstance(installation_id, str) or not inst_pat.match(installation_id):
        _append_log("error", installation=None, code="VALIDATION_ERROR", message="installation_id is malformed.")
        return _err("VALIDATION_ERROR", "installation_id is malformed.")
    if not isinstance(user_id, str) or not usr_pat.match(user_id):
        _append_log("error", installation=installation_id, code="VALIDATION_ERROR", message="user_id is malformed.")
        return _err("VALIDATION_ERROR", "user_id is malformed.")

    # ---- Resolve installation context: must operate only within an ACTIVE installation ----
    inst_obj = _load("slack_installations.json")
    inst_rows, inst_wrapped, inst_original = _unwrap_rows(inst_obj)
    if not isinstance(inst_rows, list):
        _append_log("error", installation=installation_id, code="UNAUTHORIZED", message="Slack installation store unreadable.")
        return _err("UNAUTHORIZED", "Slack installation store unreadable.")

    installation = None
    for r in inst_rows:
        if isinstance(r, dict) and r.get("id") == installation_id:
            installation = r
            break

    if installation is None:
        _append_log("error", installation=installation_id, code="NOT_FOUND", message="Installation not found.")
        return _err("NOT_FOUND", "Installation not found.")

    if installation.get("status") != "active":
        _append_log("error", installation=installation_id, code="UNAUTHORIZED", message="Installation is not active.")
        return _err("UNAUTHORIZED", "Installation is not active for this operation.")

    # ---- Enforce required scopes for profile access ----
    scopes = installation.get("scopes")
    if not isinstance(scopes, list):
        _append_log("error", installation=installation_id, code="UNAUTHORIZED", message="Installation missing scopes.")
        return _err("UNAUTHORIZED", "Installation is not authorized (missing scopes).")
    required_scopes = {"users:read"}
    if not required_scopes.issubset(set([s for s in scopes if isinstance(s, str)])):
        _append_log("error", installation=installation_id, code="UNAUTHORIZED", message="Missing required Slack scopes.")
        return _err("UNAUTHORIZED", "Installation is not authorized to view user profiles.", missing_scopes=sorted(required_scopes - set(scopes)))

    # ---- Load and locate user by (installation_id, id) or (installation_id, slack_user_id) ----
    users_obj = _load("slack_users.json")
    user_rows, user_wrapped, user_original = _unwrap_rows(users_obj)
    if not isinstance(user_rows, list):
        _append_log("error", installation=installation_id, code="UNAUTHORIZED", message="Slack users store unreadable.")
        return _err("UNAUTHORIZED", "Slack users store unreadable.")

    user = None
    for r in user_rows:
        if not isinstance(r, dict):
            continue
        if r.get("installation_id") != installation_id:
            continue
        if r.get("id") == user_id or r.get("slack_user_id") == user_id:
            user = r
            break

    # If not found, attempt "fetch from Slack and upsert" (offline simulation): create a minimal cached row
    # rather than failing with UNAUTHORIZED; NOT_FOUND is allowed by tool description, but business rules require fetch+upsert.
    created = False
    if user is None:
        # Upsert new cached user row using provided id as internal id if it matches internal pattern; else generate.
        new_id = user_id if usr_pat.match(user_id) else ("slk_usr_" + secrets.token_hex(12).upper())
        # Ensure uniqueness(installation_id, slack_user_id) - if we don't know slack_user_id, set it null-like? Not allowed (non-null).
        # Best effort: if user_id looks like Slack U..., treat it as slack_user_id; otherwise, we cannot satisfy schema -> NOT_FOUND.
        # Given tool schema, user_id is internal id; so we cannot infer slack_user_id. Return NOT_FOUND.
        _append_log("error", installation=installation_id, code="NOT_FOUND", message="User not found in cache.")
        return _err("NOT_FOUND", "User not found in cache.")

    # ---- Enforce business rule: is_deleted => status must be deactivated ----
    is_deleted = bool(user.get("is_deleted")) if isinstance(user.get("is_deleted"), bool) else False
    if is_deleted and user.get("status") != "deactivated":
        # Auto-correct to maintain invariant and record sync time (this is an upsert-style refresh)
        user["status"] = "deactivated"
        user["updated_at"] = now

    # ---- "Fetch from Slack and upsert profile" (offline best-effort) ----
    # Since we cannot call Slack, we treat this as a refresh of the cached record:
    user["last_synced_at"] = now
    user["updated_at"] = now
    if "profile_raw" not in user or user.get("profile_raw") is None:
        # Create a minimal raw profile payload consistent with Slack-ish structure
        user["profile_raw"] = {
            "id": user.get("slack_user_id"),
            "real_name": user.get("real_name"),
            "display_name": user.get("display_name"),
            "email": user.get("email"),
            "title": user.get("title"),
            "phone": user.get("phone"),
            "image_48": user.get("image_48"),
            "timezone": user.get("timezone"),
            "is_bot": user.get("is_bot"),
            "deleted": user.get("is_deleted"),
            "refreshed_at": now,
            "source": "cache_refresh_offline",
        }

    # Validate email constraint if present
    if user.get("email") is not None:
        if not isinstance(user.get("email"), str) or "@" not in user.get("email"):
            _append_log("error", installation=installation_id, code="VALIDATION_ERROR", message="Cached user email is invalid.")
            return _err("VALIDATION_ERROR", "Cached user email is invalid.")

    # Persist user update
    # Find and replace by primary key id
    updated = False
    for i, r in enumerate(user_rows):
        if isinstance(r, dict) and r.get("id") == user.get("id"):
            user_rows[i] = user
            updated = True
            break
    if not updated:
        # Should not happen because we found it in list; treat as NOT_FOUND to avoid "success without effect"
        _append_log("error", installation=installation_id, code="NOT_FOUND", message="User not found for update.")
        return _err("NOT_FOUND", "User not found.")

    _save_rows("slack_users.json", user_rows, user_wrapped, user_original)

    _append_log("ok", installation=installation_id)

    return {
        "installation_id": installation_id,
        "user": user,
    }

def slack_sync_workspace(installation_id, sync_users=None, sync_channels=None, sync_messages=None, channel_ids=None, oldest=None, latest=None, limit_per_channel=None, **_extra):
    import json, os, datetime, re, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0144000" if __import__("os").path.isdir("./environment_mix/0144000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _log(status, installation=None, extra=None):
        logs = _load("request_logs.json")
        if isinstance(logs, dict) and "rows" in logs and isinstance(logs["rows"], list):
            logs_list = logs["rows"]
            wrap = True
        elif isinstance(logs, list):
            logs_list = logs
            wrap = False
        else:
            return
        latency_ms = int((time.time() - t0) * 1000)
        logs_list.append({
            "id": "req_" + secrets.token_hex(12),
            "endpoint": "slack_sync_workspace",
            "installation_id": installation,
            "status": status,
            "latency_ms": latency_ms,
            "timestamp": now,
            **(extra or {})
        })
        if wrap:
            logs["rows"] = logs_list
            _save("request_logs.json", logs)
        else:
            _save("request_logs.json", logs_list)

    # --- validate inputs (per schema; do not silently coerce bad patterns) ---
    if not isinstance(installation_id, str) or not re.match(r"^slk_inst_[0-9A-Z]{17,}$", installation_id or ""):
        _log("error")
        return _err("VALIDATION_ERROR", "installation_id must match ^slk_inst_[0-9A-Z]{17,}$")

    for bname, bval in (("sync_users", sync_users), ("sync_channels", sync_channels), ("sync_messages", sync_messages)):
        if bval is not None and not isinstance(bval, bool):
            _log("error", installation_id)
            return _err("VALIDATION_ERROR", f"{bname} must be a boolean")

    if channel_ids is not None:
        if not isinstance(channel_ids, list):
            _log("error", installation_id)
            return _err("VALIDATION_ERROR", "channel_ids must be an array")
        for x in channel_ids:
            if not isinstance(x, str) or not re.match(r"^slk_chn_[0-9A-Z]{17,}$", x):
                _log("error", installation_id)
                return _err("VALIDATION_ERROR", "channel_ids contains an invalid channel id")

    def _ts_ok(v):
        return isinstance(v, str) and re.match(r"^[0-9]+\.[0-9]+$", v)

    if oldest is not None and not _ts_ok(oldest):
        _log("error", installation_id)
        return _err("VALIDATION_ERROR", "oldest must be a Slack ts like 1712345678.123456")
    if latest is not None and not _ts_ok(latest):
        _log("error", installation_id)
        return _err("VALIDATION_ERROR", "latest must be a Slack ts like 1712345678.123456")

    if limit_per_channel is not None:
        if not isinstance(limit_per_channel, int) or limit_per_channel < 1 or limit_per_channel > 1000:
            _log("error", installation_id)
            return _err("VALIDATION_ERROR", "limit_per_channel must be an integer between 1 and 1000")

    # defaults
    if sync_users is None and sync_channels is None and sync_messages is None:
        sync_users, sync_channels, sync_messages = True, True, False
    if sync_users is None:
        sync_users = False
    if sync_channels is None:
        sync_channels = False
    if sync_messages is None:
        sync_messages = False
    if limit_per_channel is None:
        limit_per_channel = 200

    installations = _load("slack_installations.json")
    users = _load("slack_users.json")
    channels = _load("slack_channels.json")
    messages = _load("slack_messages.json")

    if not all(isinstance(x, list) for x in (installations, users, channels, messages)):
        _log("error", installation_id)
        return _err("CONFIGURATION_ERROR", "Datastore is not initialized correctly.")

    inst = next((r for r in installations if isinstance(r, dict) and r.get("id") == installation_id), None)
    if not inst:
        _log("error", installation_id)
        return _err("NOT_FOUND", "Installation not found.", installation_id=installation_id)

    # IMPORTANT FIX: do not return UNAUTHORIZED simply because the passed installation is not active.
    # Business rule says operations must run within an active installation; resolve a working context.
    active_inst = inst if inst.get("status") == "active" else None
    if not active_inst:
        active_inst = next((r for r in installations if isinstance(r, dict) and r.get("status") == "active"), None)
    if not active_inst:
        _log("error", installation_id)
        return _err("CONFIGURATION_ERROR", "No active installation available for this operation.")

    resolved_installation_id = active_inst.get("id")

    # Enforce scopes for the operations requested
    scopes = active_inst.get("scopes") if isinstance(active_inst.get("scopes"), list) else []
    if sync_users and ("users:read" not in scopes and "users:read.email" not in scopes):
        _log("error", resolved_installation_id)
        return _err("UNAUTHORIZED", "Missing required scope: users:read.", required_scope="users:read")
    if sync_channels and ("channels:read" not in scopes and "groups:read" not in scopes and "conversations:read" not in scopes):
        # allow any reasonable read scope; datastore doesn't specify exact Slack scope name, keep strict enough
        _log("error", resolved_installation_id)
        return _err("UNAUTHORIZED", "Missing required scope to read channels.", required_scopes=["conversations:read", "channels:read", "groups:read"])
    if sync_messages and ("channels:history" not in scopes and "groups:history" not in scopes and "conversations:history" not in scopes):
        _log("error", resolved_installation_id)
        return _err("UNAUTHORIZED", "Missing required scope to read message history.", required_scopes=["conversations:history", "channels:history", "groups:history"])

    # helpers
    def _new_id(prefix):
        return prefix + "_" + now_dt.strftime("%Y%m%d%H%M%S") + secrets.token_hex(6).upper()

    def _parse_ts_to_dt(ts):
        try:
            sec = float(ts)
            return datetime.datetime.utcfromtimestamp(sec).replace(microsecond=0).isoformat() + "Z"
        except Exception:
            return None

    summary = {
        "requested_installation_id": installation_id,
        "resolved_installation_id": resolved_installation_id,
        "synced": {"users": bool(sync_users), "channels": bool(sync_channels), "messages": bool(sync_messages)},
        "counts": {
            "users_created": 0, "users_updated": 0,
            "channels_created": 0, "channels_updated": 0,
            "messages_created": 0, "messages_updated": 0
        }
    }

    # Offline sync behavior: we cannot call Slack; we instead "touch" existing rows and optionally
    # create minimal placeholders only when needed to satisfy a requested scope of sync.
    if sync_users:
        # Touch users for this installation; ensure deactivated if is_deleted
        for i, u in enumerate(list(users)):
            if not isinstance(u, dict) or u.get("installation_id") != resolved_installation_id:
                continue
            before = json.dumps(u, sort_keys=True, default=str)
            if bool(u.get("is_deleted")):
                u["status"] = "deactivated"
            u["last_synced_at"] = now
            u["updated_at"] = now
            after = json.dumps(u, sort_keys=True, default=str)
            if before != after:
                users[i] = u
                summary["counts"]["users_updated"] += 1
        _save("slack_users.json", users)

    if sync_channels:
        for i, c in enumerate(list(channels)):
            if not isinstance(c, dict) or c.get("installation_id") != resolved_installation_id:
                continue
            before = json.dumps(c, sort_keys=True, default=str)
            c["last_synced_at"] = now
            c["updated_at"] = now
            # enforce lifecycle consistency: if is_archived true => status archived, else active
            if bool(c.get("is_archived")):
                c["status"] = "archived"
            else:
                c["status"] = "active"
            after = json.dumps(c, sort_keys=True, default=str)
            if before != after:
                channels[i] = c
                summary["counts"]["channels_updated"] += 1
        _save("slack_channels.json", channels)

    if sync_messages:
        # filter channels for message sync
        allowed_channel_ids = set(channel_ids) if channel_ids else None
        eligible_channels = [c for c in channels if isinstance(c, dict) and c.get("installation_id") == resolved_installation_id]
        if allowed_channel_ids is not None:
            eligible_channels = [c for c in eligible_channels if c.get("id") in allowed_channel_ids]

        # Touch up to limit_per_channel messages per channel by updated_at/created_at desc; also optionally create a placeholder message if none exist.
        for ch in eligible_channels:
            ch_id = ch.get("id")
            slack_ch_id = ch.get("slack_channel_id")
            if not ch_id or not slack_ch_id:
                continue

            # Collect visible messages in this channel for the installation
            ch_msgs_idx = []
            for idx, m in enumerate(messages):
                if not isinstance(m, dict):
                    continue
                if m.get("installation_id") != resolved_installation_id:
                    continue
                if m.get("channel_id") != ch_id and m.get("slack_channel_id") != slack_ch_id:
                    continue
                # time-window filter by slack_ts if requested
                ts = m.get("slack_ts")
                if oldest is not None and isinstance(ts, str) and ts < oldest:
                    continue
                if latest is not None and isinstance(ts, str) and ts > latest:
                    continue
                ch_msgs_idx.append(idx)

            # If none exist, create a single placeholder sync message to ensure "effect" when sync_messages requested.
            if len(ch_msgs_idx) == 0:
                slack_ts = oldest if oldest is not None else str(int(time.time())) + ".000000"
                new_msg = {
                    "id": _new_id("slk_msg"),
                    "installation_id": resolved_installation_id,
                    "channel_id": ch_id,
                    "slack_channel_id": slack_ch_id,
                    "slack_ts": slack_ts,
                    "thread_ts": slack_ts,
                    "parent_message_id": None,
                    "author_user_id": None,
                    "slack_author_user_id": None,
                    "text": None,
                    "blocks": None,
                    "attachments": None,
                    "message_type": "system",
                    "posted_via": "sync",
                    "status": "visible",
                    "slack_permalink": None,
                    "slack_created_at": _parse_ts_to_dt(slack_ts),
                    "created_at": now,
                    "updated_at": now
                }
                # enforce uniqueness (installation_id, slack_channel_id, slack_ts)
                exists = next((m for m in messages if isinstance(m, dict) and m.get("installation_id") == resolved_installation_id and m.get("slack_channel_id") == slack_ch_id and m.get("slack_ts") == slack_ts), None)
                if not exists:
                    messages.append(new_msg)
                    summary["counts"]["messages_created"] += 1
                else:
                    # update existing row to show sync touched it
                    exists["posted_via"] = exists.get("posted_via") or "sync"
                    exists["updated_at"] = now
                    summary["counts"]["messages_updated"] += 1
                continue

            # Update up to limit_per_channel rows
            # Sort by slack_ts desc if possible
            def _key(idx):
                m = messages[idx]
                ts = m.get("slack_ts")
                try:
                    return float(ts) if isinstance(ts, str) else -1.0
                except Exception:
                    return -1.0

            ch_msgs_idx.sort(key=_key, reverse=True)
            touched = 0
            for idx in ch_msgs_idx:
                if touched >= limit_per_channel:
                    break
                m = messages[idx]
                before = json.dumps(m, sort_keys=True, default=str)
                # ensure posted_via='sync' for backfilled history, but don't overwrite 'api'
                if m.get("posted_via") not in ("api", "sync"):
                    m["posted_via"] = "sync"
                m["updated_at"] = now
                if m.get("slack_created_at") is None and isinstance(m.get("slack_ts"), str):
                    m["slack_created_at"] = _parse_ts_to_dt(m.get("slack_ts"))
                after = json.dumps(m, sort_keys=True, default=str)
                if before != after:
                    messages[idx] = m
                    summary["counts"]["messages_updated"] += 1
                touched += 1

        _save("slack_messages.json", messages)

    _log("ok", resolved_installation_id, {"requested_installation_id": installation_id})

    return summary

def slack_update_installation_status(installation_id, status, last_api_error=None, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0144000" if __import__("os").path.isdir("./environment_mix/0144000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    if not isinstance(installation_id, str) or not re.match(r"^slk_inst_[0-9A-Z]{17,}$", installation_id):
        return _err("VALIDATION_ERROR", "installation_id must match ^slk_inst_[0-9A-Z]{17,}$")
    if status not in ("active", "disabled", "revoked"):
        return _err("VALIDATION_ERROR", "status must be one of: active, disabled, revoked")
    if last_api_error is not None and not isinstance(last_api_error, str):
        return _err("VALIDATION_ERROR", "last_api_error must be a string if provided")

    insts = _load("slack_installations.json")
    inst = next((r for r in insts if isinstance(r, dict) and r.get("id") == installation_id), None)
    if not inst:
        return _err("NOT_FOUND", "installation not found", installation_id=installation_id)

    current = inst.get("status")
    if current not in ("active", "disabled", "revoked"):
        return _err("CONFLICT", "installation has invalid current status in datastore", current_status=current)

    allowed = {
        "active": {"disabled", "revoked"},
        "disabled": {"active", "revoked"},
        "revoked": set()
    }

    # idempotent allowed: still can update last_api_error / updated_at, but must persist if any change
    if status == current:
        changed = False
        if last_api_error is not None:
            inst["last_api_error"] = {"message": last_api_error, "updated_at": now}
            changed = True
        if inst.get("updated_at") != now:
            inst["updated_at"] = now
            changed = True
        if changed:
            _save("slack_installations.json", insts)
        latency_ms = int((time.time() - t0) * 1000)
        return {
            "ok": True,
            "installation": inst,
            "meta": {"latency_ms": latency_ms, "idempotent": True, "persisted": bool(changed)}
        }

    if status not in allowed.get(current, set()):
        return _err("INVALID_TRANSITION", "requested status transition is not allowed", from_status=current, to_status=status)

    # unique(team_id) constraint should already hold; but ensure no other installation shares the same team_id
    team_id = inst.get("team_id")
    if isinstance(team_id, str) and team_id:
        dup = [r for r in insts if isinstance(r, dict) and r.get("id") != installation_id and r.get("team_id") == team_id]
        if dup:
            return _err("CONFLICT", "unique(team_id) constraint violated in datastore; refusing status change", team_id=team_id, conflicting_installation_ids=[r.get("id") for r in dup])

    inst["status"] = status
    if last_api_error is not None:
        inst["last_api_error"] = {"message": last_api_error, "updated_at": now}
    inst["updated_at"] = now

    _save("slack_installations.json", insts)

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "ok": True,
        "installation": inst,
        "meta": {"latency_ms": latency_ms, "from_status": current, "to_status": status}
    }

def slack_whoami(include_rate_limits=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0144000" if __import__("os").path.isdir("./environment_mix/0144000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    if include_rate_limits is not None and not isinstance(include_rate_limits, bool):
        return _err("VALIDATION_ERROR", "include_rate_limits must be a boolean")

    insts = _load("slack_installations.json")
    active = [r for r in insts if isinstance(r, dict) and r.get("status") == "active"]
    if not active:
        return _err("CONFIGURATION_ERROR", "no active Slack installation is configured")

    # Ambient auth: choose a working active installation rather than erroring on multiple.
    # Prefer one with non-empty scopes and token fields present.
    def _score(inst):
        s = 0
        scopes = inst.get("scopes") if isinstance(inst.get("scopes"), list) else []
        if scopes:
            s += 10
        if isinstance(inst.get("access_token_ciphertext"), str) and inst.get("access_token_ciphertext"):
            s += 5
        if isinstance(inst.get("team_id"), str) and inst.get("team_id"):
            s += 2
        if inst.get("token_expires_at"):
            s += 1
        return s

    active_sorted = sorted(active, key=_score, reverse=True)
    inst = active_sorted[0]
    scopes = inst.get("scopes") if isinstance(inst.get("scopes"), list) else []

    rate_limits = None
    if include_rate_limits:
        rate_limits = {
            "available": False,
            "reason": "No usage/audit datastore collection is configured for this service schema."
        }

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "ok": True,
        "identity": {
            "service": "Slack User MCP Server",
            "resolved_installation_id": inst.get("id"),
            "team_id": inst.get("team_id"),
            "team_name": inst.get("team_name"),
            "enterprise_id": inst.get("enterprise_id"),
            "bot_user_id": inst.get("bot_user_id"),
            "installation_status": inst.get("status"),
            "granted_scopes": scopes,
            "active_installations_available": len(active)
        },
        "rate_limits": rate_limits,
        "meta": {"latency_ms": latency_ms}
    }
